const pair = (tr, en) => [tr, en];
const event = (id, tr, en, textTr, textEn, gate, month, cost, effects, wait, delay, later, laterTr, laterEn, extra = {}) => ({
  id,
  title: pair(tr, en),
  text: pair(textTr, textEn),
  gate,
  month,
  choices: [
    { id: "act", label: pair("Kaynak ayır ve uygula", "Fund and implement"), cost, effects, delay, later, text: pair(laterTr, laterEn) },
    { id: "decline", label: pair("Talebi reddet", "Decline the request"), cost: 0, effects: wait },
  ],
  expires: 3,
  wave2Extra: true,
  ...extra,
});

